def count_matching_ranges(n, numbers):
    total_ways = 0
    prefix_sum = [0] * (n + 1)

    # Calculate prefix sums
    for i in range(1, n + 1):
        prefix_sum[i] = prefix_sum[i - 1] + numbers[i - 1]

    # Dictionary to store products and their indices
    product_indices = {}

    for i in range(n):
        product = numbers[i]

        if product in product_indices:
            for j in product_indices[product]:
                if j < i - 1:
                    total_ways += i - j - 1

        if product not in product_indices:
            product_indices[product] = []
        product_indices[product].append(i)

    return total_ways

